function resolveCommand(command: string): string {
  if (!isWindows) {
    return command;
  }
  const base = basename(command).toLowerCase();
  if (extname(base)) {
    return command;
  }
  if (["pnpm", "yarn"].includes(base)) {
    return `${command}.cmd`;
  }
  return command;
}

